// Package: Microsoft.SemanticKernel, Microsoft.Extensions.AI

using Microsoft.SemanticKernel;
using Microsoft.Extensions.AI;
using System.ComponentModel;

public class OrderPlugin
{
    [KernelFunction, Description("Retrieve order details by order ID.")]
    public Task<string> GetOrderAsync(string orderId)
    {
        return Task.FromResult(orderId == "ABC123"
            ? "Order ABC123 | Status: Shipped | Items: 3 | Total: $149.99"
            : "Order not found.");
    }

    [KernelFunction, Description("Check if an order is eligible for a discount.")]
    public Task<string> CheckDiscountAsync(string orderId)
    {
        return Task.FromResult(orderId == "ABC123"
            ? "Eligible for 10% loyalty discount."
            : "Not eligible for discount.");
    }

    [KernelFunction, Description("Apply a discount code to an order.")]
    public Task<string> ApplyDiscountAsync(string orderId, string discountCode)
    {
        return Task.FromResult(
            $"Discount {discountCode} applied to order {orderId}. New total: $135.00");
    }
}

public class PlannerAgentDemo
{
    private readonly Kernel _kernel;
    private readonly string _modelId = "gpt-4o";
    private readonly string _apiKey = "your-api-key";

    public PlannerAgentDemo()
    {
        _kernel = Kernel.CreateBuilder()
            .AddOpenAIChatCompletion(_modelId, new OpenAIClient(_apiKey))
            .Build();

        _kernel.Plugins.AddFromType<OrderPlugin>();
    }

    public async Task RunAsync(string userGoal, CancellationToken ct = default)
    {
        // SequentialPlanner was deprecated in SK v1.19+.
        // For simple plan-and-execute flows, prefer the SK Process Framework
        // or a hand-rolled function-calling loop with KernelArguments.

        var arguments = new KernelArguments();
        arguments["goal"] = userGoal;

        var prompt = $"""
Goal: {userGoal}

Available functions:
- OrderPlugin.GetOrderAsync(orderId)
- OrderPlugin.CheckDiscountAsync(orderId)
- OrderPlugin.ApplyDiscountAsync(orderId, discountCode)

Decide which functions to call and in what order.
""";

        var result = await _kernel.InvokePromptAsync<string>(prompt, arguments, ct);

        Console.WriteLine("=== Model Plan ===");
        Console.WriteLine(result);
        // Expected: Check order ABC123 and apply loyalty discount

        // Expected plan steps:
        // Step 1: OrderPlugin.GetOrderAsync(orderId: "ABC123")
        // Step 2: OrderPlugin.CheckDiscountAsync(orderId: "ABC123")
        // Step 3: OrderPlugin.ApplyDiscountAsync(orderId: "ABC123", discountCode: "LOYALTY10")
    }
}

